/**
 * The tokenizer parity corpus.
 *
 * The JavaScript tokenizer lives in `dsh-plugin-dbgraph-service`; the native writer must reimplement it
 * in Rust, and the two implementations are only honest if they agree token for token. This fixture is
 * the shared corpus: expectations were generated by running the JS tokenizer (never hand-written), the
 * JS side asserts against them here, and `crates/dbgraph-indexer` reads the same file.
 *
 * Bump the corpus when a tokenization rule changes — a silent rule drift between the two writers would
 * degrade recall rather than fail, which is the failure mode this file exists to make impossible.
 */

import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'
import { tokenizeForSearch } from 'dsh-plugin-dbgraph-service'

interface TokenFixture {
  readonly text: string
  readonly tokens: readonly string[]
}

const FIXTURE_PATH = join(fileURLToPath(new URL('.', import.meta.url)), 'fixtures', 'tokens.json')
const CORPUS = JSON.parse(readFileSync(FIXTURE_PATH, 'utf8')) as TokenFixture[]

describe('tokenizer parity corpus', () => {
  it('is the corpus the native writer reads too', () => {
    expect(CORPUS.length).toBeGreaterThanOrEqual(15)
    for (const entry of CORPUS) {
      expect(entry.text.length).toBeGreaterThan(0)
      expect(entry.tokens.length).toBeGreaterThan(0)
    }
  })

  it('tokenizes every fixture case exactly', () => {
    for (const entry of CORPUS) {
      expect(tokenizeForSearch(entry.text), entry.text).toEqual(entry.tokens)
    }
  })

  it('is deterministic and deduplicated', () => {
    for (const entry of CORPUS) {
      const first = tokenizeForSearch(entry.text)
      expect(tokenizeForSearch(entry.text)).toEqual(first)
      expect(new Set(first).size).toBe(first.length)
    }
  })
})
